// =====================================================================
// SATU-SATUNYA NODE YANG PERLU ANDA UBAH.
// =====================================================================
const cfg = {
  // Domain LM App di production, TANPA garis miring di akhir.
  baseUrl: 'https://GANTI-DENGAN-DOMAIN-LM-APP',

  // Nomor yang menerima permintaan approval. WAJIB nomor supervisor/owner
  // yang sudah diisi di Owner > Karyawan > Edit > No. WhatsApp. Kalau belum
  // terdaftar di sana, aplikasi menolak dengan 403 dan itu memang benar.
  approverPhone: '628XXXXXXXXXX',

  // Instance Evolution API untuk MENGIRIM. Yang ada di VPS: notif-outlet, laundry-ai.
  evoInstance: 'notif-outlet',

  // Jangan ganggu approver untuk pengajuan yang baru saja masuk.
  minAgeHours: 2,

  // Ambang "segera jatuh tempo" untuk ringkasan tugas (1-72).
  dueSoonHours: 12,
};

// Gagal keras kalau belum diisi. Lebih baik berhenti di sini daripada
// menembak domain yang tidak ada lalu diam-diam tidak mengirim apa pun.
if (cfg.baseUrl.includes('GANTI')) {
  throw new Error('Isi baseUrl di node Konfigurasi dengan domain LM App Anda.');
}
if (!/^62\d{8,13}$/.test(cfg.approverPhone)) {
  throw new Error('Isi approverPhone dengan format 62..., bukan 08... atau +62...');
}
cfg.baseUrl = cfg.baseUrl.replace(/\/+$/, '');

return [{ json: cfg }];

// Ambil hanya antrean yang menunggu persetujuan supervisor.
// Tahap lain (verifikasi Admin Ops, pembayaran owner) sengaja tidak disentuh:
// tidak ada aksi WhatsApp untuk keduanya.
const cfg = $('1. Konfigurasi').first().json;
const digest = $input.first().json;

const pending = (digest.requisitions && digest.requisitions.pendingApproval) || [];
const layak = pending.filter((r) => (r.ageHours ?? 0) >= cfg.minAgeHours);

console.log(`[LM] pending=${pending.length} layak=${layak.length} (minAgeHours=${cfg.minAgeHours})`);

// Array kosong = cabang berhenti di sini. Tidak ada pengajuan, tidak ada pesan.
return layak.map((r) => ({ json: r }));

// Ubah hasil penerbitan token jadi teks WhatsApp.
//
// Token dikirim apa adanya dan harus disalin kembali oleh approver. Itu memang
// lebih repot daripada balas "YA", dan itulah maksudnya: "YA" bisa datang dari
// siapa pun yang tahu formatnya, sedangkan kode ini sekali pakai, 60 menit,
// dan hanya sah dari nomor yang menerimanya.
const cfg = $('1. Konfigurasi').first().json;
const out = [];

for (const item of $input.all()) {
  const res = item.json || {};
  const status = res.statusCode;
  const body = res.body || {};

  if (status !== 200 || !body.ok || !body.token) {
    // Dilewati, bukan dihentikan: satu pengajuan yang gagal tidak boleh
    // menahan sisanya. Pengajuan ini tetap bisa disetujui di dalam aplikasi.
    console.log(`[LM] gagal minta token (HTTP ${status}): ${JSON.stringify(body).slice(0, 200)}`);
    continue;
  }

  const r = body.requisition || {};
  const rupiah = new Intl.NumberFormat('id-ID').format(Number(r.amount) || 0);

  const text = [
    '🧾 *Persetujuan Pengajuan*',
    '',
    `${r.title || 'Pengajuan Pembelian'}`,
    `Rp ${rupiah}`,
    '',
    'Balas dengan MENYALIN salah satu baris di bawah ini persis seperti adanya:',
    '',
    `SETUJU ${body.token}`,
    '',
    `TOLAK ${body.token}`,
    '',
    '⏳ Berlaku 60 menit, sekali pakai, dan hanya sah dari nomor ini.',
    'Pembayaran tetap dilakukan Owner di dalam aplikasi.',
  ].join('\n');

  out.push({ json: { number: cfg.approverPhone, text, requisitionId: r.id } });
}

return out;
